impl<T: Payments> Payments for AuditedPayments<T> {
    fn pay(&self, p: &Payment) -> Result<Receipt, Error> {
        let actor = current_subject();
        self.sink.record(&actor, "pay", &p.id, Outcome::Attempt);

        let result = self.inner.pay(p);

        self.sink.record(&actor, "pay", &p.id, outcome_of(&result));
        result
    }
}

