impl<S, R> Service<R> for Audited<S>
where S: Service<R>,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = Instrumented<S::Future>;      // records outcome on poll

    fn call(&mut self, req: R) -> Self::Future {
        self.sink.record(&self.actor, "call", Outcome::Attempt);
        Instrumented { inner: self.inner.call(req), sink: self.sink.clone() }
    }
}
